<?php
require __DIR__.'/lib.php';require_login();header('Cache-Control: private, no-store');header('Content-Type: application/json');$lock=null;$changed=false;
try{if(!om_ready()||!access_page_allowed('order_monitor'))throw new Exception('Order monitoring access required.');ob_start();$id=(int)($_REQUEST['order_id']??0);if($_SERVER['REQUEST_METHOD']==='GET'){if(($_GET['view']??'')==='references')or_popup($id);elseif(($_GET['view']??'')==='history')oi_history($id);else oi_manual_form($id);}else{verify_csrf();$a=$_POST['action']??'';if(!(ic_cancel_role()&&in_array($a,['manual_preview','manual_apply'],true)))om_require();
 if($a==='or_preview'){$p=or_reference_plan($id,$_POST);$token=bin2hex(random_bytes(24));$_SESSION['or_preview']=['plan'=>$p,'token'=>$token];or_preview_html($p,$token);}
 elseif($a==='or_apply'){$saved=$_SESSION['or_preview']??null;if(!$saved||empty($_POST['confirm_ack'])||!hash_equals($saved['token'],(string)($_POST['token']??'')))throw new Exception('Review and acknowledge reference changes first.');$lock=inventory_write_lock();or_reference_apply($saved['plan']);unset($_SESSION['or_preview']);$changed=true;echo '<h2>References Saved</h2><p>Booking, assigned Order ID and tracking are searchable. No stock or reservation changed.</p><button class="btn primary" data-oi-reload>Done / Refresh Orders</button>';}
 elseif($a==='manual_preview'){unset($_SESSION['oi_manual']);$p=oi_manual_plan($id,$_POST);$token=bin2hex(random_bytes(24));$_SESSION['oi_manual']=['token'=>$token,'plan'=>$p];oi_manual_preview_html($p,$token);}
 elseif($a==='manual_apply'){$saved=$_SESSION['oi_manual']??null;if(!$saved||empty($_POST['confirm_ack'])||!hash_equals($saved['token'],(string)($_POST['token']??'')))throw new Exception('Review and confirm this update first.');$lock=inventory_write_lock();$r=oi_manual_apply($saved['plan']);$changed=true;unset($_SESSION['oi_manual']);echo '<h2>Status Update Saved</h2><p>'.e($r['order']['order_no'].' · '.$r['action']).'</p><p>The order and history have been updated. Stock follows the reviewed effect.</p><button type="button" class="btn secondary" data-oi="history" data-order="'.$r['order']['id'].'">View Update History</button>';echo '<button type="button" class="btn primary" data-oi-reload>Done / Refresh Orders</button>';}
 elseif($a==='exclude'){$orders=json_decode((string)($_POST['selection_json']??'[]'),true,512,JSON_THROW_ON_ERROR);if(!is_array($orders)||!$orders||count($orders)>5000)throw new Exception('Select 1 to 5000 orders.');$b=om_upload((int)$_POST['upload_id']);om_owner($b);if((int)$b['revision']!==(int)$_POST['revision'])throw new Exception('Review changed. Refresh this page.');$reason=process_reason($_POST['reason']??'');$undo=($_POST['undo']??'0')==='1';$token=bin2hex(random_bytes(24));$_SESSION['oi_exclude']=['token'=>$token,'id'=>$b['id'],'revision'=>$b['revision'],'orders'=>$orders,'reason'=>$reason,'undo'=>$undo];echo '<h2>'.($undo?'Restore orders to upload?':'Remove orders from this upload?').'</h2><p>'.count($orders).' complete orders selected.</p><p>Existing orders, status and stock will not change. '.($undo?'Restored orders will be revalidated.':'These orders will be skipped when this upload is confirmed.').'</p><div class="oi-selection">';foreach($orders as $no){if(!is_scalar($no))throw new Exception('Invalid selection.');echo '<p>'.e($no).'</p>';}echo '</div><p>Reason: '.e($reason).'</p>';oi_form('exclude_apply',['token'=>$token]);echo '<label class="oi-ack"><input type="checkbox" name="confirm_ack" value="1" required> I want to continue with the selected orders.</label><button class="btn primary">'.($undo?'Yes, Restore Orders':'Yes, Remove from Upload').'</button></form>';}
 elseif($a==='exclude_apply'){$s=$_SESSION['oi_exclude']??null;if(!$s||empty($_POST['confirm_ack'])||!hash_equals($s['token'],(string)($_POST['token']??'')))throw new Exception('Review and confirm the selection first.');$lock=inventory_write_lock();$n=oi_exclude($s['id'],$s['revision'],$s['orders'],$s['reason'],$s['undo']);$changed=true;unset($_SESSION['oi_exclude']);echo '<h2>Upload Review Updated</h2><p>'.$n.' orders '.($s['undo']?'restored':'removed from this upload').'. No stocks changed.</p><button type="button" class="btn primary" data-oi-reload>Refresh Verification</button>';}
 else throw new Exception('Unknown action.');}echo json_encode(['ok'=>true,'changed'=>$changed,'html'=>ob_get_clean()]);
}catch(Throwable $e){if(ob_get_level())ob_end_clean();http_response_code(400);echo json_encode(['ok'=>false,'message'=>safe_error_message($e)]);}finally{if($lock)inventory_write_unlock($lock);}
